-- ============================================================================
-- COLORSHINE MES V2
-- 22_rm_opening_inventory_plant2000_from_rm_grn.sql
--
-- ONE-TIME OPENING RM INVENTORY LOAD
-- Source: RM_GRN.xml
-- Scope : Plant 2000 only
-- Filter: MATERIAL_CODE LIKE 'R_HR%'
--
-- Source statistics:
--   RM_GRN.xml rows              : 8,714
--   Qualified R_HR* RM rows      : 8,692
--   Qualified quantity           : 222,112.298 MT
--   Storage 2001                 : 8,644 coils / 220,861.863 MT
--   Storage RC01                 :    48 coils /   1,250.435 MT
--
-- IMPORTANT:
-- * This is opening inventory, not historical GRN transaction replay.
-- * Existing live MES GRN inventory is NOT deleted.
-- * The unified RM Stores view makes a live MES batch take precedence over the
--   opening snapshot when the same Plant+Batch exists in both sources.
-- * QA fields are set to PENDING_QA until the separate RM_QA file is loaded.
-- ============================================================================

ROLLBACK;
SET search_path TO mes, public;
BEGIN;

VALUES ('1.9.4','Plant 2000 one-time RM opening inventory from RM_GRN.xml and unified RM Stores inventory')
ON CONFLICT (version_no) DO NOTHING;

CREATE TABLE IF NOT EXISTS mes.inventory_master (
    inventory_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    source_row_no integer NOT NULL,
    source_file varchar(120) NOT NULL,
    material_type varchar(20),
    stock_stage varchar(10),
    plant_code varchar(4) NOT NULL REFERENCES mes.plant_master(plant_code),
    storage_location varchar(10),
    material_code varchar(60),
    batch_no varchar(40) NOT NULL,
    batch_qty_mt numeric(14,4),
    qa_grade varchar(30),
    thickness_mm numeric(10,4),
    width_mm numeric(12,3),
    length_value numeric(14,3),
    temper varchar(40),
    coating varchar(40),
    jet_printing varchar(80),
    stock_generated_date date,
    stock_age_days integer,
    mes_po varchar(40),
    so_no varchar(20),
    so_line_item varchar(10),
    so_thickness_mm numeric(10,4),
    so_width_mm numeric(12,3),
    so_temper varchar(40),
    so_quality varchar(40),
    so_coating varchar(40),
    so_min_wt_mt numeric(14,4),
    so_max_wt_mt numeric(14,4),
    so_logo varchar(100),
    so_spangle varchar(100),
    so_jet_printing varchar(100),
    so_tll varchar(100),
    mother_rm_batch varchar(40),
    supplier_batch varchar(100),
    heat_no varchar(100),
    mother_stock_grn_date date,
    mother_stock_grn_age_days integer,
    rm_steel_grade varchar(50),
    carbon varchar(40),
    manganese varchar(40),
    sulphur varchar(40),
    phosphorus varchar(40),
    silicon varchar(40),
    aluminium varchar(40),
    carbon_equivalent varchar(40),
    nitrogen varchar(40),
    copper varchar(40),
    molybdenum varchar(40),
    chromium varchar(40),
    nickel varchar(40),
    rm_supplier varchar(200),
    imported_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ux_inventory_master_plant_batch UNIQUE (plant_code,batch_no)
);

-- Preserve RM_GRN source fields needed by Stores, audit and future QA merge.
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS source_system varchar(30);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS stock_status varchar(30);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS material_description varchar(200);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS product_group varchar(30);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS product_type varchar(30);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS rm_source varchar(40);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS sap_grn_no varchar(20);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS sap_po_no varchar(20);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS sap_po_item varchar(10);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS po_delivery_date date;
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS movement_type varchar(10);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS eq_spec varchar(80);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS eq_spec_group varchar(80);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS eq_sub_spec varchar(80);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS chapter_id varchar(40);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS chapter_type varchar(20);
ALTER TABLE mes.inventory_master ADD COLUMN IF NOT EXISTS crown numeric(14,4);

CREATE INDEX IF NOT EXISTS ix_inventory_master_plant_stage
ON mes.inventory_master(plant_code,stock_stage,material_type);
CREATE INDEX IF NOT EXISTS ix_inventory_master_search
ON mes.inventory_master(plant_code,batch_no,material_code,storage_location);
CREATE INDEX IF NOT EXISTS ix_inventory_master_rm_grn
ON mes.inventory_master(plant_code,sap_grn_no,sap_po_no);

-- Remove the previous 983-row mixed RM/WIP/FG test snapshot and any prior
-- execution of this one-time RM_GRN opening load.
DELETE FROM mes.inventory_master
WHERE plant_code='2000'
  AND source_file IN ('InventoryMaster_MES.xlsx','RM_GRN.xml');

