-- --------------------------------------------------------------------------
-- Unified RM Stores inventory
--
-- Live MES inventory wins for quantity/stock status. Opening-load data is
-- retained as metadata so the next RM_QA upload can enrich the same batch.
-- --------------------------------------------------------------------------
CREATE OR REPLACE VIEW mes.vw_rm_store_inventory AS
WITH live AS (
  SELECT
    ('LIVE:' || i.batch_id::text) AS row_id,
    'LIVE_MES'::varchar(30) AS source_system,
    NULL::integer AS source_row_no,
    'LIVE_MES'::varchar(120) AS source_file,
    'HR'::varchar(20) AS material_type,
    'RM'::varchar(10) AS stock_stage,
    i.plant_code,
    i.storage_location,
    i.sap_material_code AS material_code,
    COALESCE(m.material_description, q.material_description) AS material_description,
    COALESCE(m.product_group, 'HRC') AS product_group,
    COALESCE(m.product_type, 'COIL') AS product_type,
    i.batch_no,
    i.on_hand_weight_mt::numeric(14,4) AS batch_qty_mt,
    m.qa_grade,
    i.stock_status,
    i.batch_thickness_mm::numeric(10,4) AS thickness_mm,
    i.batch_width_mm::numeric(12,3) AS width_mm,
    m.length_value,
    m.temper,
    m.coating,
    m.jet_printing,
    COALESCE(m.stock_generated_date, q.grn_posting_date) AS stock_generated_date,
    CASE
      WHEN COALESCE(m.stock_generated_date, q.grn_posting_date) IS NULL THEN NULL
      ELSE CURRENT_DATE - COALESCE(m.stock_generated_date, q.grn_posting_date)
    END AS stock_age_days,
    COALESCE(m.rm_source, q.sap_vendor_no) AS rm_source,
    COALESCE(q.sap_grn_no, i.sap_grn_no) AS sap_grn_no,
    COALESCE(q.sap_po_no, m.sap_po_no) AS sap_po_no,
    COALESCE(q.sap_po_item, m.sap_po_item) AS sap_po_item,
    m.po_delivery_date,
    COALESCE(m.movement_type,'101') AS movement_type,
    m.eq_spec,
    m.eq_spec_group,
    m.eq_sub_spec,
    m.chapter_id,
    m.chapter_type,
    m.crown,
    m.mes_po,
    m.so_no,
    m.so_line_item,
    m.so_thickness_mm,
    m.so_width_mm,
    m.so_temper,
    m.so_quality,
    m.so_coating,
    m.so_min_wt_mt,
    m.so_max_wt_mt,
    m.so_logo,
    m.so_spangle,
    m.so_jet_printing,
    m.so_tll,
    COALESCE(m.mother_rm_batch, i.batch_no) AS mother_rm_batch,
    COALESCE(m.supplier_batch, i.vendor_batch_no) AS supplier_batch,
    COALESCE(m.heat_no, i.heat_no) AS heat_no,
    COALESCE(m.mother_stock_grn_date, q.grn_posting_date) AS mother_stock_grn_date,
    CASE
      WHEN COALESCE(m.mother_stock_grn_date, q.grn_posting_date) IS NULL THEN NULL
      ELSE CURRENT_DATE - COALESCE(m.mother_stock_grn_date, q.grn_posting_date)
    END AS mother_stock_grn_age_days,
    COALESCE(m.rm_steel_grade, i.hr_grade) AS rm_steel_grade,
    m.carbon,m.manganese,m.sulphur,m.phosphorus,m.silicon,m.aluminium,
    m.carbon_equivalent,m.nitrogen,m.copper,m.molybdenum,m.chromium,m.nickel,
    COALESCE(m.rm_supplier, i.supplier_name) AS rm_supplier,
    COALESCE(m.imported_at, i.last_movement_at) AS imported_at,
    GREATEST(COALESCE(m.updated_at,'1900-01-01'::timestamptz),i.last_movement_at) AS updated_at
  FROM mes.vw_rm_inventory i
  LEFT JOIN mes.inventory_master m
    ON m.plant_code=i.plant_code AND m.batch_no=i.batch_no
  LEFT JOIN mes.vw_grn_ud_queue q
    ON q.batch_id=i.batch_id
),
opening_only AS (
  SELECT
    ('OPEN:' || m.inventory_id::text) AS row_id,
    COALESCE(m.source_system,'OPENING_LOAD') AS source_system,
    m.source_row_no,m.source_file,m.material_type,m.stock_stage,m.plant_code,m.storage_location,
    m.material_code,m.material_description,m.product_group,m.product_type,m.batch_no,m.batch_qty_mt,
    m.qa_grade,COALESCE(m.stock_status,'QUALITY_HOLD') AS stock_status,m.thickness_mm,m.width_mm,
    m.length_value,m.temper,m.coating,m.jet_printing,m.stock_generated_date,
    COALESCE(m.stock_age_days,CASE WHEN m.stock_generated_date IS NULL THEN NULL ELSE CURRENT_DATE-m.stock_generated_date END) AS stock_age_days,
    m.rm_source,m.sap_grn_no,m.sap_po_no,m.sap_po_item,m.po_delivery_date,m.movement_type,
    m.eq_spec,m.eq_spec_group,m.eq_sub_spec,m.chapter_id,m.chapter_type,m.crown,
    m.mes_po,m.so_no,m.so_line_item,m.so_thickness_mm,m.so_width_mm,m.so_temper,m.so_quality,
    m.so_coating,m.so_min_wt_mt,m.so_max_wt_mt,m.so_logo,m.so_spangle,m.so_jet_printing,m.so_tll,
    m.mother_rm_batch,m.supplier_batch,m.heat_no,m.mother_stock_grn_date,
    COALESCE(m.mother_stock_grn_age_days,CASE WHEN m.mother_stock_grn_date IS NULL THEN NULL ELSE CURRENT_DATE-m.mother_stock_grn_date END) AS mother_stock_grn_age_days,
    m.rm_steel_grade,m.carbon,m.manganese,m.sulphur,m.phosphorus,m.silicon,m.aluminium,
    m.carbon_equivalent,m.nitrogen,m.copper,m.molybdenum,m.chromium,m.nickel,
    m.rm_supplier,m.imported_at,m.updated_at
  FROM mes.inventory_master m
  WHERE UPPER(COALESCE(m.stock_stage,''))='RM'
    AND m.material_code LIKE 'R_HR%'
    AND NOT EXISTS (
      SELECT 1
      FROM mes.vw_rm_inventory i
      WHERE i.plant_code=m.plant_code AND i.batch_no=m.batch_no
    )
)
SELECT * FROM live
UNION ALL
SELECT * FROM opening_only;

-- Plant Stock report keeps future WIP/FG snapshot rows, but replaces RM rows
-- by the unified RM Stores source so live GRNs always appear.
CREATE OR REPLACE VIEW mes.vw_plant_stock_report AS
SELECT
  row_id AS inventory_id,
  source_row_no,source_file,material_type,stock_stage,plant_code,storage_location,
  material_code,batch_no,batch_qty_mt,qa_grade,thickness_mm,width_mm,length_value,
  temper,coating,jet_printing,stock_generated_date,stock_age_days,
  mes_po,so_no,so_line_item,so_thickness_mm,so_width_mm,so_temper,so_quality,
  so_coating,so_min_wt_mt,so_max_wt_mt,so_logo,so_spangle,so_jet_printing,so_tll,
  mother_rm_batch,supplier_batch,heat_no,mother_stock_grn_date,mother_stock_grn_age_days,
  rm_steel_grade,carbon,manganese,sulphur,phosphorus,silicon,aluminium,carbon_equivalent,
  nitrogen,copper,molybdenum,chromium,nickel,rm_supplier,imported_at,updated_at
FROM mes.vw_rm_store_inventory
UNION ALL
SELECT
  inventory_id::text,source_row_no,source_file,material_type,stock_stage,plant_code,storage_location,
  material_code,batch_no,batch_qty_mt,qa_grade,thickness_mm,width_mm,length_value,
  temper,coating,jet_printing,stock_generated_date,stock_age_days,
  mes_po,so_no,so_line_item,so_thickness_mm,so_width_mm,so_temper,so_quality,
  so_coating,so_min_wt_mt,so_max_wt_mt,so_logo,so_spangle,so_jet_printing,so_tll,
  mother_rm_batch,supplier_batch,heat_no,mother_stock_grn_date,mother_stock_grn_age_days,
  rm_steel_grade,carbon,manganese,sulphur,phosphorus,silicon,aluminium,carbon_equivalent,
  nitrogen,copper,molybdenum,chromium,nickel,rm_supplier,imported_at,updated_at
FROM mes.inventory_master
WHERE UPPER(COALESCE(stock_stage,'')) IN ('WIP','FG');

COMMIT;

-- --------------------------------------------------------------------------
-- Verification
-- Before RM_QA load, PRIME qty is expected to be zero for opening rows.
-- The live accepted GRN remains in the unified view and is de-duplicated if
-- the same batch also exists in RM_GRN.xml.
-- --------------------------------------------------------------------------
SELECT
  plant_code,
  count(*)::int AS rm_coils,
  round(sum(batch_qty_mt),3) AS total_qty_mt,
  round(sum(batch_qty_mt) FILTER (WHERE UPPER(COALESCE(qa_grade,''))='PRIME'),3) AS prime_qty_mt,
  round(sum(batch_qty_mt) FILTER (WHERE storage_location='2001'),3) AS storage_2001_qty_mt,
  round(sum(batch_qty_mt) FILTER (WHERE UPPER(storage_location)='RC01'),3) AS storage_rc01_qty_mt
FROM mes.vw_rm_store_inventory
WHERE plant_code='2000'
GROUP BY plant_code;

SELECT material_code,count(*) AS coils,round(sum(batch_qty_mt),3) AS qty_mt
FROM mes.vw_rm_store_inventory
WHERE plant_code='2000'
GROUP BY material_code
ORDER BY material_code;

SELECT source_system,count(*) AS rows,round(sum(batch_qty_mt),3) AS qty_mt
FROM mes.vw_rm_store_inventory
WHERE plant_code='2000'
GROUP BY source_system
ORDER BY source_system;
